// ── the builder's vocabulary: one field handle per member, memberships per refinement ──

class PeptideFields(path: List<String> = emptyList()) : Fields(path) {
    val code: TextField get() = TextField(fieldPath + "code")
}

class BacteriaStrainFields(path: List<String> = emptyList()) : Fields(path) {
    val name: TextField get() = TextField(fieldPath + "name")
}

class FermenterRunFields(path: List<String> = emptyList()) : Fields(path) {
    val vessel: TextField get() = TextField(fieldPath + "vessel")
    val startedOn: DateField get() = DateField(fieldPath + "startedOn")
}

class VendorFields(path: List<String> = emptyList()) : Fields(path) {
    val name: TextField get() = TextField(fieldPath + "name")
}

class FermentationFields(path: List<String> = emptyList()) : Fields(path) {
    val strain: BacteriaStrainFields get() = BacteriaStrainFields(fieldPath + "strain")
    val run: FermenterRunFields get() = FermenterRunFields(fieldPath + "run")
    fun isUnclaimedOrigin(): Expr = isA("UnclaimedOrigin")
}

class ExternalOrderFields(path: List<String> = emptyList()) : Fields(path) {
    val vendor: VendorFields get() = VendorFields(fieldPath + "vendor")
